from fastapi.testclient import TestClient
from app.main import app

client = TestClient(app)

def test_filter_completed_true_returns_only_completed_tasks():
    r = client.get("/tasks/?completed=true")
    assert r.status_code == 200
    tasks = r.json()
    assert len(tasks) == 6
    returned_ids = {t["id"] for t in tasks}
    assert returned_ids == {1, 2, 3, 9, 15, 19}
    for t in tasks:
        assert t["completed"] is True

from fastapi.testclient import TestClient
from app.main import app

client = TestClient(app)

def test_filter_completed_false_returns_only_incomplete_tasks():
    r = client.get("/tasks/?completed=false")
    assert r.status_code == 200
    tasks = r.json()
    assert len(tasks) == 14
    returned_ids = {t["id"] for t in tasks}
    assert returned_ids == {4, 5, 6, 7, 8, 10, 11, 12, 13, 14, 16, 17, 18, 20}
    for t in tasks:
        assert t["completed"] is False
